// Transform ERPNext Patient to FHIR Patient Resource
const patient = $input.item.json.data;

// Build FHIR Patient resource
const fhirPatient = {
  resourceType: "Patient",
  identifier: [
    {
      system: "http://hospital.example.org/mrn",
      type: {
        coding: [{
          system: "http://terminology.hl7.org/CodeSystem/v2-0203",
          code: "MR"
        }]
      },
      value: patient.name
    }
  ],
  active: !patient.disabled,
  name: [
    {
      use: "official",
      text: patient.patient_name,
      family: patient.last_name,
      given: [patient.first_name, patient.middle_name].filter(n => n)
    }
  ],
  gender: patient.sex?.toLowerCase(),
  birthDate: patient.dob,
  telecom: [
    {
      system: "phone",
      value: patient.mobile,
      use: "mobile"
    },
    {
      system: "email",
      value: patient.email
    }
  ].filter(t => t.value),
  address: [
    {
      use: "home",
      line: [patient.address],
      city: patient.city,
      state: patient.state,
      postalCode: patient.pincode,
      country: patient.country
    }
  ],
  maritalStatus: {
    coding: [{
      system: "http://terminology.hl7.org/CodeSystem/v3-MaritalStatus",
      code: getMaritalStatusCode(patient.marital_status)
    }]
  },
  extension: []
};

// Add blood group extension if present
if (patient.blood_group) {
  fhirPatient.extension.push({
    url: "http://erpnext.example.org/fhir/StructureDefinition/blood-group",
    valueCodeableConcept: {
      coding: [{
        code: patient.blood_group,
        display: patient.blood_group
      }]
    }
  });
}

function getMaritalStatusCode(status) {
  const mapping = {
    'Single': 'S',
    'Married': 'M',
    'Divorced': 'D',
    'Widowed': 'W'
  };
  return mapping[status] || 'UNK';
}

return { json: fhirPatient };

// Transform FHIR Patient to ERPNext Patient
const fhirPatient = $input.item.json;

// Extract name components
const officialName = fhirPatient.name?.find(n => n.use === 'official') || fhirPatient.name?.[0] || {};

// Build ERPNext Patient data
const erpnextPatient = {
  doctype: "Patient",
  patient_name: officialName.text || `${officialName.given?.[0]} ${officialName.family}`,
  first_name: officialName.given?.[0],
  middle_name: officialName.given?.[1],
  last_name: officialName.family,
  sex: fhirPatient.gender?.charAt(0).toUpperCase() + fhirPatient.gender?.slice(1),
  dob: fhirPatient.birthDate,
  mobile: fhirPatient.telecom?.find(t => t.system === 'phone' && t.use === 'mobile')?.value,
  phone: fhirPatient.telecom?.find(t => t.system === 'phone' && t.use === 'home')?.value,
  email: fhirPatient.telecom?.find(t => t.system === 'email')?.value,
  disabled: fhirPatient.active === false ? 1 : 0
};

// Extract address
const homeAddress = fhirPatient.address?.find(a => a.use === 'home') || fhirPatient.address?.[0];
if (homeAddress) {
  erpnextPatient.address = homeAddress.line?.[0];
  erpnextPatient.city = homeAddress.city;
  erpnextPatient.state = homeAddress.state;
  erpnextPatient.pincode = homeAddress.postalCode;
  erpnextPatient.country = homeAddress.country;
}

// Extract marital status
if (fhirPatient.maritalStatus?.coding?.[0]?.code) {
  const maritalMapping = {
    'S': 'Single',
    'M': 'Married',
    'D': 'Divorced',
    'W': 'Widowed'
  };
  erpnextPatient.marital_status = maritalMapping[fhirPatient.maritalStatus.coding[0].code];
}

// Extract blood group from extension
const bloodGroupExt = fhirPatient.extension?.find(e => e.url.includes('blood-group'));
if (bloodGroupExt) {
  erpnextPatient.blood_group = bloodGroupExt.valueCodeableConcept?.coding?.[0]?.code;
}

// Extract MRN from identifier
const mrnIdentifier = fhirPatient.identifier?.find(i => i.type?.coding?.some(c => c.code === 'MR'));
if (mrnIdentifier) {
  erpnextPatient.name = mrnIdentifier.value;
}

return { json: erpnextPatient };
